package main
import("bufio";"fmt";"os";"os/exec";"runtime";"strings")
func main(){if runtime.GOOS!="windows"{fmt.Println("Windows somente.");return};fmt.Println("NAXAPA - Instalador/Verificador de Dependências");fmt.Println();if !isAdmin(){fmt.Println("Solicitando permissão de administrador...");relaunchAdmin();return};if _,e:=exec.LookPath("winget.exe");e!=nil{fatal("WinGet não foi encontrado. Atualize o 'App Installer' pela Microsoft Store e execute novamente.")}
 install("Microsoft.DotNet.SDK.10",".NET 10 SDK");install("Google.Chrome","Google Chrome");install("Git.Git","Git");ensureSqlExpress();firewall();fmt.Println("\nDependências principais verificadas.");fmt.Print("Deseja preparar também Flutter e Android Studio para o NAXAPA Mobile? [s/N]: ");r,_:=bufio.NewReader(os.Stdin).ReadString('\n');if strings.EqualFold(strings.TrimSpace(r),"s"){install("Google.AndroidStudio","Android Studio");installFlutter()};fmt.Println("\nValidação:");run("dotnet","--version");run("git","--version");checkService();fmt.Println("\nConcluído. Pressione ENTER.");bufio.NewReader(os.Stdin).ReadString('\n')}
func install(id,name string){fmt.Println("\n-- "+name);args:=[]string{"install","--id",id,"--exact","--accept-package-agreements","--accept-source-agreements","--silent","--disable-interactivity"};c:=exec.Command("winget",args...);c.Stdout=os.Stdout;c.Stderr=os.Stderr;if e:=c.Run();e!=nil{fmt.Printf("Aviso: WinGet retornou erro para %s. Verificando se já está instalado...\n",name)}}
func ensureSqlExpress(){if serviceExists(){fmt.Println("\n-- SQL Server Express: instância SQLEXPRESS já encontrada.");return};fmt.Println("\n-- SQL Server Express");ids:=[]string{"Microsoft.SQLServer.2025.Express","Microsoft.SQLServer.2022.Express"};for _,id:=range ids{show:=exec.Command("winget","show","--id",id,"--exact","--accept-source-agreements");if show.Run()==nil{install(id,"SQL Server Express");if serviceExists(){return}}};fmt.Println("ATENÇÃO: não foi possível confirmar a instalação do SQLEXPRESS. Instale SQL Server Express manualmente antes de iniciar a Gestão.")}
func serviceExists()bool{return exec.Command("sc","query","MSSQL$SQLEXPRESS").Run()==nil}
func checkService(){if serviceExists(){exec.Command("sc","start","MSSQL$SQLEXPRESS").Run();fmt.Println("SQL Server SQLEXPRESS: detectado") }else{fmt.Println("SQL Server SQLEXPRESS: NÃO detectado")}}
func firewall(){ps:=`if(-not (Get-NetFirewallRule -DisplayName 'NAXAPA Gestão 5180' -ErrorAction SilentlyContinue)){New-NetFirewallRule -DisplayName 'NAXAPA Gestão 5180' -Direction Inbound -Protocol TCP -LocalPort 5180 -Action Allow -Profile Private,Domain | Out-Null}`;exec.Command("powershell","-NoProfile","-ExecutionPolicy","Bypass","-Command",ps).Run()}
func installFlutter(){fmt.Println("\n-- Flutter SDK (canal stable)");ps:=`$dst=Join-Path $env:USERPROFILE 'development\flutter'; if(-not (Test-Path (Join-Path $dst 'bin\flutter.bat'))){New-Item -ItemType Directory -Force (Split-Path $dst)|Out-Null; git clone --depth 1 --branch stable https://github.com/flutter/flutter.git $dst}; $p=[Environment]::GetEnvironmentVariable('Path','User'); $bin=Join-Path $dst 'bin'; if(($p -split ';') -notcontains $bin){[Environment]::SetEnvironmentVariable('Path',($p.TrimEnd(';')+';'+$bin),'User')}; & (Join-Path $bin 'flutter.bat') --version`;c:=exec.Command("powershell","-NoProfile","-ExecutionPolicy","Bypass","-Command",ps);c.Stdout=os.Stdout;c.Stderr=os.Stderr;c.Run()}
func isAdmin()bool{return exec.Command("net","session").Run()==nil}
func relaunchAdmin(){exe,_:=os.Executable();cmd:=exec.Command("powershell","-NoProfile","-Command",fmt.Sprintf("Start-Process -FilePath '%s' -Verb RunAs",strings.ReplaceAll(exe,"'","''")));cmd.Run()}
func run(name string,args ...string){c:=exec.Command(name,args...);o,e:=c.CombinedOutput();if e!=nil{fmt.Printf("%s: não disponível (%v)\n",name,e)}else{fmt.Printf("%s: %s\n",name,strings.TrimSpace(string(o)))}}
func fatal(s string){fmt.Println("ERRO: "+s);bufio.NewReader(os.Stdin).ReadString('\n');os.Exit(1)}
